class Solution {
public:
    int minSideJumps(vector<int>& obstacles) {
        const int INF = 1e9;
        int dp1 = INF, dp2 = 0, dp3 = INF;
        int sz = obstacles.size();
        for (int i = 0; i + 1 < sz; i++) {
            int o = obstacles[i];
            int oNext = obstacles[i + 1];
            int m = min({dp1, dp2, dp3});
            if (o != 1) dp1 = min(dp1, m + 1);
            if (o != 2) dp2 = min(dp2, m + 1);
            if (o != 3) dp3 = min(dp3, m + 1);
            if (oNext == 1) dp1 = INF;
            else if (oNext == 2) dp2 = INF;
            else if (oNext == 3) dp3 = INF;
        }
        return min({dp1, dp2, dp3});
    }
};
